11	// AscendC FusedAddRmsnorm kernel — merged strategies: merge_n, single_row, splitd
12	// Computes: x = hidden_states + residual; y = (x * rsqrt(mean(x^2) + eps)) * weight
13	// Supports float32, float16, bfloat16
14	// Format: Abs-style with dtype dispatch in __global__ entry
15	
16	#include "kernel_operator.h"
17	
18	constexpr int32_t BUFFER_NUM = 1;
19	
20	// ---------------------------------------------------------------------------
21	// Inline helpers
22	// ---------------------------------------------------------------------------
23	
24	__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
25	{
26	    if (b == 0U) { return 0U; }
27	    return (a + b - 1U) / b;
28	}
29	
30	template <typename T>
31	__aicore__ inline void LoadGmToUb(
32	    AscendC::LocalTensor<T> &dst,
33	    AscendC::GlobalTensor<T> src,
34	    uint32_t count)
35	{
36	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
37	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
38	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
39	}
40	
41	template <typename T>
42	__aicore__ inline void StoreUbToGm(
43	    AscendC::GlobalTensor<T> dst,
44	    AscendC::LocalTensor<T> &src,
45	    uint32_t count)
46	{
47	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
48	    AscendC::DataCopyPad(dst, src, copyParams);
49	}
50	
51	// =========================================================================
52	// Strategy-agnostic helper functions
53	// =========================================================================
54	
55	__aicore__ inline int32_t BlockCountHelper(int32_t M, int32_t blockM)
56	{
57	    if (blockM == 0) { return 0; }
58	    return (M + blockM - 1) / blockM;
59	}
60	
61	template <typename T>
62	__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
63	{
64	    if constexpr (std::is_same_v<T, bfloat16_t>) {
65	        return AscendC::RoundMode::CAST_ROUND;
66	    }
67	    return AscendC::RoundMode::CAST_NONE;
68	}
69	
70	template <typename T>
71	__aicore__ inline void PrepareInputTensorHelper(
72	    AscendC::LocalTensor<float> &dst,
73	    AscendC::LocalTensor<T> &src,
74	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
75	    int32_t count)
76	{
77	    if constexpr (std::is_same_v<T, float>) {
78	        dst = src.template ReinterpretCast<float>();
79	    } else {
80	        dst = castBuf.Get<float>();
81	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
82	        AscendC::PipeBarrier<PIPE_V>();
83	    }
84	}
85	
86	template <typename T>
87	__aicore__ inline void PrepareOutputTensorHelper(
88	    AscendC::LocalTensor<float> &dst,
89	    AscendC::LocalTensor<T> &out,
90	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf)
91	{
92	    if constexpr (std::is_same_v<T, float>) {
93	        dst = out.template ReinterpretCast<float>();
94	    } else {
95	        dst = castBuf.Get<float>();
96	    }
97	}
98	
99	template <typename T>
100	__aicore__ inline void FinalizeOutputTensorHelper(
101	    AscendC::LocalTensor<T> &out,
102	    AscendC::LocalTensor<float> &src,
103	    int32_t count)
104	{
105	    if constexpr (!std::is_same_v<T, float>) {
106	        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
107	        AscendC::PipeBarrier<PIPE_V>();
108	    }
109	}
110	
111	template <typename F>
112	__aicore__ inline void ProcessLoop(
113	    F &&processRowFn,
114	    int32_t tasksPerCore, int32_t M, int32_t blockM, int32_t subBlockRows_)
115	{
116	    if ASCEND_IS_AIV {
117	        const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
118	        const int subBlockIdx = AscendC::GetSubBlockIdx();
119	
120	        for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
121	            const int bx = coreIdx * tasksPerCore + localIdx;
122	            if (bx >= BlockCountHelper(M, blockM)) {
123	                continue;
124	            }
125	
126	            for (int row = 0; row < subBlockRows_; ++row) {
127	                const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
128	                if (rowIdx < M) {
129	                    processRowFn(rowIdx);
130	                }
131	            }
132	        }
133	    }
134	}
135	
136	// =========================================================================
137	// Base class for SingleRow and SplitD strategies — shared Init and members
138	// =========================================================================
139	
140	template <typename dataType>
141	class FusedAddRmsnormKernelBase {
142	public:
143	    __aicore__ inline void InitBase(
144	        GM_ADDR hs, GM_ADDR res, GM_ADDR weight, GM_ADDR y,
145	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
146	        int32_t tasksPerCore, float eps, float invN)
147	    {
148	        this->M = M;
149	        this->N = N;
150	        this->blockM = blockM;
151	        this->usedCoreNum = usedCoreNum;
152	        this->tasksPerCore = tasksPerCore;
153	        this->eps = eps;
154	        this->invN = invN;
155	
156	        hsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(hs), static_cast<uint64_t>(M) * N);
157	        resGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(res), static_cast<uint64_t>(M) * N);
158	        weightGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(weight), N);
159	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);
160	    }
161	
162	protected:
163	    int32_t M = 0;
164	    int32_t N = 0;
165	    int32_t blockM = 0;
166	    int32_t usedCoreNum = 0;
167	    int32_t tasksPerCore = 0;
168	    float eps = 0.0f;
169	    float invN = 0.0f;
170	    int subBlockRows_ = 0;
171	
172	    AscendC::TPipe pipe;
173	    AscendC::GlobalTensor<dataType> hsGM_;
174	    AscendC::GlobalTensor<dataType> resGM_;
175	    AscendC::GlobalTensor<dataType> weightGM_;
176	    AscendC::GlobalTensor<dataType> yGM_;
177	};
178	
179	// =========================================================================
180	// Strategy 1: merge_n — preferred when N <= 1024
181	// =========================================================================
182	
183	template <typename dataType>
184	class FusedAddRmsnormMergeNKernel {
185	public:
186	    __aicore__ inline void Init(
187	        GM_ADDR hs, GM_ADDR res, GM_ADDR weight, GM_ADDR y,
188	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
189	        int32_t tasksPerCore, int32_t rowFactor, float eps, float invN)
190	    {
191	        this->M = M;
192	        this->N = N;
193	        this->blockM = blockM;
194	        this->usedCoreNum = usedCoreNum;
195	        this->tasksPerCore = tasksPerCore;
196	        this->rowFactor = rowFactor;
197	        this->eps = eps;
198	        this->invN = invN;
199	
200	        hsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(hs), static_cast<uint64_t>(M) * N);
201	        resGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(res), static_cast<uint64_t>(M) * N);
202	        weightGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(weight), N);
203	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);
204	
205	        if ASCEND_IS_AIV { InitAivBuffers(); }
206	    }
207	
208	    __aicore__ inline void InitAivBuffers()
209	    {
210	        subBlockRows_ = blockM / AscendC::GetSubBlockNum();
211	        rowLoops_ = subBlockRows_ / rowFactor;
212	        pipe.InitBuffer(weightTmpBuf_, N * sizeof(dataType));
213	        pipe.InitBuffer(hsInQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
214	        pipe.InitBuffer(resInQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
215	        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
216	        pipe.InitBuffer(scaleBuf_, kMergeRowFactor * N * sizeof(float));
217	        pipe.InitBuffer(weightTileBuf_, kMergeRowFactor * N * sizeof(float));
218	        pipe.InitBuffer(weightBroadcastTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
219	        pipe.InitBuffer(scaleBroadcastTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
220	        pipe.InitBuffer(reduceBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
221	        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
222	        pipe.InitBuffer(invRmsBuf_, kMergeRowFactor * sizeof(float));
223	        pipe.InitBuffer(addBuf_, kMergeRowFactor * N * sizeof(float));
224	        if constexpr (!std::is_same_v<dataType, float>) {
225	            pipe.InitBuffer(hsCastBuf_, kMergeRowFactor * N * sizeof(float));
226	            pipe.InitBuffer(resCastBuf_, kMergeRowFactor * N * sizeof(float));
227	            pipe.InitBuffer(weightCastBuf_, N * sizeof(float));
228	            pipe.InitBuffer(yCastBuf_, kMergeRowFactor * N * sizeof(float));
229	        }
230	
231	        const uint32_t weightSrcShape[2] = {1U, static_cast<uint32_t>(N)};
232	        const uint32_t weightDstShape[2] = {
233	            static_cast<uint32_t>(kMergeRowFactor),
234	            static_cast<uint32_t>(N),
235	        };
236	
237	        weightInLocal_ = weightTmpBuf_.Get<dataType>();
238	        LoadGmToUb(weightInLocal_, weightGM_, static_cast<uint32_t>(N));
239	        AscendC::PipeBarrier<PIPE_MTE2>();
240	        AscendC::PipeBarrier<PIPE_ALL>();
241	        PrepareInputTensorHelper(weightLocal_, weightInLocal_, weightCastBuf_, N);
242	
243	        weightTileLocal_ = weightTileBuf_.Get<float>();
244	        weightBroadcastTmpLocal_ = weightBroadcastTmpBuf_.Get<uint8_t>();
245	        AscendC::PipeBarrier<PIPE_ALL>();
246	        AscendC::Broadcast<float, 2, 0>(
247	            weightTileLocal_,
248	            weightLocal_,
249	            weightDstShape,
250	            weightSrcShape,
251	            weightBroadcastTmpLocal_);
252	        AscendC::PipeBarrier<PIPE_V>();
253	    }
254	
255	    __aicore__ inline void Process()
256	    {
257	        if ASCEND_IS_AIV {
258	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
259	            const int subBlockIdx = AscendC::GetSubBlockIdx();
260	
261	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
262	                const int bx = coreIdx * tasksPerCore + localIdx;
263	                if (bx >= BlockCountHelper(M, blockM)) {
264	                    continue;
265	                }
266	
267	                for (int r = 0; r < rowLoops_; ++r) {
268	                    const int rowBase = bx * blockM + subBlockIdx * subBlockRows_ + r * rowFactor;
269	                    const int validRows = M - rowBase;
270	                    if (validRows > 0) {
271	                        ProcessRows(rowBase, validRows >= kMergeRowFactor ? kMergeRowFactor : validRows);
272	                    }
273	                }
274	            }
275	        }
276	    }
277	
278	private:
279	    static constexpr int kMergeRowFactor = 8;
280	
281	    __aicore__ inline void CopyInHs(int32_t rowBase, int32_t count)
282	    {
283	        hsInLocal_ = hsInQueue_.AllocTensor<dataType>();
284	        LoadGmToUb(hsInLocal_, hsGM_[static_cast<uint64_t>(rowBase) * N], static_cast<uint32_t>(count));
285	        hsInQueue_.EnQue(hsInLocal_);
286	    }
287	
288	    __aicore__ inline void CopyInRes(int32_t rowBase, int32_t count)
289	    {
290	        resInLocal_ = resInQueue_.AllocTensor<dataType>();
291	        LoadGmToUb(resInLocal_, resGM_[static_cast<uint64_t>(rowBase) * N], static_cast<uint32_t>(count));
292	        resInQueue_.EnQue(resInLocal_);
293	    }
294	
295	    __aicore__ inline void CopyOutY(int32_t rowBase, int32_t count)
296	    {
297	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
298	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowBase) * N], yOutLocal_, static_cast<uint32_t>(count));
299	        yOutQueue_.FreeTensor(yOutLocal_);
300	    }
301	
302	    __aicore__ inline void ComputeSingleRow()
303	    {
304	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
305	        scaleLocal_ = scaleBuf_.Get<float>();
306	        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
307	        sumLocal_ = sumBuf_.Get<float>();
308	        addLocal_ = addBuf_.Get<float>();
309	        invRmsLocal_ = invRmsBuf_.Get<float>();
310	
311	        hsInLocal_ = hsInQueue_.DeQue<dataType>();
312	        resInLocal_ = resInQueue_.DeQue<dataType>();
313	        PrepareInputTensorHelper<dataType>(hsLocal_, hsInLocal_, hsCastBuf_, N);
314	        PrepareInputTensorHelper<dataType>(resLocal_, resInLocal_, resCastBuf_, N);
315	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
316	
317	        // x = hidden_states + residual
318	        AscendC::Add(addLocal_, hsLocal_, resLocal_, N);
319	        // x^2
320	        AscendC::Mul(yLocal_, addLocal_, addLocal_, N);
321	        // mean(x^2) over N
322	        const uint32_t reduceShape[2] = {1U, static_cast<uint32_t>(N)};
323	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
324	            sumLocal_, yLocal_, reduceTmpLocal_, reduceShape, true);
325	        // * (1/N) + eps
326	        AscendC::Muls(sumLocal_, sumLocal_, invN, 1);
327	        AscendC::Adds(sumLocal_, sumLocal_, eps, 1);
328	        // rsqrt
329	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, 1);
330	        AscendC::PipeBarrier<PIPE_ALL>();
331	        float invRms = invRmsLocal_.GetValue(0);
332	        AscendC::PipeBarrier<PIPE_ALL>();
333	        // x * rsqrt
334	        AscendC::Muls(yLocal_, addLocal_, invRms, N);
335	        // * weight
336	        AscendC::Mul(yLocal_, yLocal_, weightLocal_, N);
337	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, N);
338	
339	        hsInQueue_.FreeTensor(hsInLocal_);
340	        resInQueue_.FreeTensor(resInLocal_);
341	        yOutQueue_.EnQue(yOutLocal_);
342	    }
343	
344	    __aicore__ inline void ComputeRows(int32_t tileSize)
345	    {
346	        const uint32_t reduceShape[2] = {
347	            static_cast<uint32_t>(kMergeRowFactor),
348	            static_cast<uint32_t>(N),
349	        };
350	        const uint32_t scaleSrcShape[2] = {
351	            static_cast<uint32_t>(kMergeRowFactor),
352	            1U,
353	        };
354	        const uint32_t scaleDstShape[2] = {
355	            static_cast<uint32_t>(kMergeRowFactor),
356	            static_cast<uint32_t>(N),
357	        };
358	
359	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
360	        scaleLocal_ = scaleBuf_.Get<float>();
361	        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
362	        sumLocal_ = sumBuf_.Get<float>();
363	        addLocal_ = addBuf_.Get<float>();
364	        invRmsLocal_ = invRmsBuf_.Get<float>();
365	        scaleBroadcastTmpLocal_ = scaleBroadcastTmpBuf_.Get<uint8_t>();
366	
367	        hsInLocal_ = hsInQueue_.DeQue<dataType>();
368	        resInLocal_ = resInQueue_.DeQue<dataType>();
369	        PrepareInputTensorHelper<dataType>(hsLocal_, hsInLocal_, hsCastBuf_, tileSize);
370	        PrepareInputTensorHelper<dataType>(resLocal_, resInLocal_, resCastBuf_, tileSize);
371	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
372	
373	        // x = hidden_states + residual
374	        AscendC::Add(addLocal_, hsLocal_, resLocal_, tileSize);
375	        // x^2
376	        AscendC::Mul(yLocal_, addLocal_, addLocal_, tileSize);
377	        // mean(x^2) over N
378	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
379	            sumLocal_, yLocal_, reduceTmpLocal_, reduceShape, true);
380	        AscendC::Muls(sumLocal_, sumLocal_, invN, kMergeRowFactor);
381	        AscendC::Adds(sumLocal_, sumLocal_, eps, kMergeRowFactor);
382	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, kMergeRowFactor);
383	        AscendC::PipeBarrier<PIPE_V>();
384	        AscendC::Broadcast<float, 2, 1>(
385	            scaleLocal_, invRmsLocal_, scaleDstShape, scaleSrcShape, scaleBroadcastTmpLocal_);
386	
387	        // x * rsqrt_broadcast
388	        AscendC::Mul(yLocal_, addLocal_, scaleLocal_, tileSize);
389	        // * weight
390	        AscendC::Mul(yLocal_, yLocal_, weightTileLocal_, tileSize);
391	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, tileSize);
392	
393	        hsInQueue_.FreeTensor(hsInLocal_);
394	        resInQueue_.FreeTensor(resInLocal_);
395	        yOutQueue_.EnQue(yOutLocal_);
396	    }
397	
398	    __aicore__ inline void ProcessSingleRow(int rowBase)
399	    {
400	        CopyInHs(rowBase, N);
401	        CopyInRes(rowBase, N);
402	        ComputeSingleRow();
403	        CopyOutY(rowBase, N);
404	    }
405	
406	    __aicore__ inline void ProcessRows(int rowBase, int validRows)
407	    {
408	        if (validRows < kMergeRowFactor) {
409	            for (int r = 0; r < validRows; ++r) {
410	                ProcessSingleRow(rowBase + r);
411	            }
412	            return;
413	        }
414	
415	        const int tileSize = kMergeRowFactor * N;
416	        CopyInHs(rowBase, tileSize);
417	        CopyInRes(rowBase, tileSize);
418	        ComputeRows(tileSize);
419	        CopyOutY(rowBase, tileSize);
420	    }
421	
422	private:
423	    int32_t M = 0;
424	    int32_t N = 0;
425	    int32_t blockM = 0;
426	    int32_t usedCoreNum = 0;
427	    int32_t tasksPerCore = 0;
428	    int32_t rowFactor = 0;
429	    float eps = 0.0f;
430	    float invN = 0.0f;
431	    int subBlockRows_ = 0;
432	    int rowLoops_ = 0;
433	
434	    AscendC::TPipe pipe;
435	    AscendC::GlobalTensor<dataType> hsGM_;
436	    AscendC::GlobalTensor<dataType> resGM_;
437	    AscendC::GlobalTensor<dataType> weightGM_;
438	    AscendC::GlobalTensor<dataType> yGM_;
439	
440	    AscendC::TBuf<AscendC::TPosition::VECCALC> weightTmpBuf_;
441	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> hsInQueue_;
442	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> resInQueue_;
443	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
444	    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleBuf_;
445	    AscendC::TBuf<AscendC::TPosition::VECCALC> weightTileBuf_;
446	    AscendC::TBuf<AscendC::TPosition::VECCALC> weightBroadcastTmpBuf_;
447	    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleBroadcastTmpBuf_;
448	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
449	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
450	    AscendC::TBuf<AscendC::TPosition::VECCALC> invRmsBuf_;
451	    AscendC::TBuf<AscendC::TPosition::VECCALC> addBuf_;
452	    AscendC::TBuf<AscendC::TPosition::VECCALC> hsCastBuf_;
453	    AscendC::TBuf<AscendC::TPosition::VECCALC> resCastBuf_;
454	    AscendC::TBuf<AscendC::TPosition::VECCALC> weightCastBuf_;
455	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
456	
457	    AscendC::LocalTensor<dataType> weightInLocal_;
458	    AscendC::LocalTensor<dataType> hsInLocal_;
459	    AscendC::LocalTensor<dataType> resInLocal_;
460	    AscendC::LocalTensor<dataType> yOutLocal_;
461	    AscendC::LocalTensor<float> weightLocal_;
462	    AscendC::LocalTensor<float> hsLocal_;
463	    AscendC::LocalTensor<float> resLocal_;
464	    AscendC::LocalTensor<float> yLocal_;
465	    AscendC::LocalTensor<float> addLocal_;
466	    AscendC::LocalTensor<float> scaleLocal_;
467	    AscendC::LocalTensor<float> weightTileLocal_;
468	    AscendC::LocalTensor<float> invRmsLocal_;
469	    AscendC::LocalTensor<uint8_t> weightBroadcastTmpLocal_;
470	    AscendC::LocalTensor<uint8_t> scaleBroadcastTmpLocal_;
471	    AscendC::LocalTensor<uint8_t> reduceTmpLocal_;
472	    AscendC::LocalTensor<float> sumLocal_;
473	};
