481	public:
482	    __aicore__ inline void Init(
483	        GM_ADDR hs, GM_ADDR res, GM_ADDR weight, GM_ADDR y,
484	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
485	        int32_t tasksPerCore, float eps, float invN)
486	    {
487	        this->InitBase(hs, res, weight, y, M, N, blockM, usedCoreNum, tasksPerCore, eps, invN);
488	
489	        if ASCEND_IS_AIV {
490	            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
491	            pipe.InitBuffer(weightTmpBuf_, N * sizeof(dataType));
492	            pipe.InitBuffer(hsInQueue_, BUFFER_NUM, N * sizeof(dataType));
493	            pipe.InitBuffer(resInQueue_, BUFFER_NUM, N * sizeof(dataType));
494	            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, N * sizeof(dataType));
495	            pipe.InitBuffer(reduceBuf_, N * sizeof(float));
496	            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
497	            pipe.InitBuffer(invRmsBuf_, sizeof(float));
498	            pipe.InitBuffer(addBuf_, N * sizeof(float));
499	            if constexpr (!std::is_same_v<dataType, float>) {
500	                pipe.InitBuffer(hsCastBuf_, N * sizeof(float));
501	                pipe.InitBuffer(resCastBuf_, N * sizeof(float));
502	                pipe.InitBuffer(weightCastBuf_, N * sizeof(float));
503	                pipe.InitBuffer(yCastBuf_, N * sizeof(float));
504	            }
505	
506	            weightInLocal_ = weightTmpBuf_.Get<dataType>();
507	            LoadGmToUb(weightInLocal_, weightGM_, static_cast<uint32_t>(N));
508	            AscendC::PipeBarrier<PIPE_MTE2>();
509	            AscendC::PipeBarrier<PIPE_ALL>();
510	            PrepareInputTensorHelper<dataType>(weightLocal_, weightInLocal_, weightCastBuf_, N);
511	        }
512	    }
513	
514	    __aicore__ inline void Process()
515	    {
516	        ProcessLoop(
517	            [this](int32_t rowIdx) { this->ProcessRow(rowIdx); },
518	            this->tasksPerCore, this->M, this->blockM, this->subBlockRows_);
519	    }
520	
521	private:
522	    __aicore__ inline void PrepareOutputTensor(
523	        AscendC::LocalTensor<float> &dst,
524	        AscendC::LocalTensor<dataType> &out,
525	        AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
526	        int32_t count)
527	    {
528	        if constexpr (std::is_same_v<dataType, float>) {
529	            dst = out.template ReinterpretCast<float>();
530	        } else {
531	            dst = castBuf.Get<float>();
532	            AscendC::Duplicate(out, static_cast<dataType>(0), count);
533	        }
534	    }
535	
536	    __aicore__ inline void CopyInHs(int32_t rowIdx)
537	    {
538	        hsInLocal_ = hsInQueue_.AllocTensor<dataType>();
539	        LoadGmToUb(hsInLocal_, hsGM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
540	        hsInQueue_.EnQue(hsInLocal_);
541	    }
542	
543	    __aicore__ inline void CopyInRes(int32_t rowIdx)
544	    {
545	        resInLocal_ = resInQueue_.AllocTensor<dataType>();
546	        LoadGmToUb(resInLocal_, resGM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
547	        resInQueue_.EnQue(resInLocal_);
548	    }
549	
550	    __aicore__ inline void CopyOutY(int32_t rowIdx)
551	    {
552	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
553	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N], yOutLocal_, static_cast<uint32_t>(N));
554	        yOutQueue_.FreeTensor(yOutLocal_);
555	    }
556	
557	    __aicore__ inline void ComputeRow()
558	    {
559	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
560	        invRmsLocal_ = invRmsBuf_.Get<float>();
561	        reduceLocal_ = reduceBuf_.Get<float>();
562	        sumLocal_ = sumBuf_.Get<float>();
563	        addLocal_ = addBuf_.Get<float>();
564	
565	        hsInLocal_ = hsInQueue_.DeQue<dataType>();
566	        resInLocal_ = resInQueue_.DeQue<dataType>();
567	        PrepareInputTensorHelper<dataType>(hsLocal_, hsInLocal_, hsCastBuf_, N);
568	        PrepareInputTensorHelper<dataType>(resLocal_, resInLocal_, resCastBuf_, N);
569	        PrepareOutputTensor(yLocal_, yOutLocal_, yCastBuf_, N);
570	
571	        // x = hidden_states + residual
572	        AscendC::Add(addLocal_, hsLocal_, resLocal_, N);
573	        // x^2 + reduce sum
574	        AscendC::Mul(yLocal_, addLocal_, addLocal_, N);
575	        AscendC::ReduceSum<float>(sumLocal_, yLocal_, reduceLocal_, N);
576	
577	        float meanSq = sumLocal_.GetValue(0) * invN + eps;
578	        AscendC::Duplicate(sumLocal_, meanSq, 1);
579	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, 1);
580	        AscendC::PipeBarrier<PIPE_ALL>();
581	        float invRms = invRmsLocal_.GetValue(0);
582	        AscendC::PipeBarrier<PIPE_ALL>();
583	
584	        // x * rsqrt
585	        AscendC::Muls(yLocal_, addLocal_, invRms, N);
586	        // * weight
587	        AscendC::Mul(yLocal_, yLocal_, weightLocal_, N);
588	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, N);
589	
590	        hsInQueue_.FreeTensor(hsInLocal_);
591	        resInQueue_.FreeTensor(resInLocal_);
592	        yOutQueue_.EnQue(yOutLocal_);
593	    }
594	
595	    __aicore__ inline void ProcessRow(int rowIdx)
596	    {
597	        CopyInHs(rowIdx);
598	        CopyInRes(rowIdx);
599	        ComputeRow();
600	        CopyOutY(rowIdx);
601	    }
