614	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
615	    AscendC::TBuf<AscendC::TPosition::VECCALC> invRmsBuf_;
616	    AscendC::TBuf<AscendC::TPosition::VECCALC> addBuf_;
617	
618	    AscendC::LocalTensor<dataType> hsInLocal_;
619	    AscendC::LocalTensor<dataType> resInLocal_;
620	    AscendC::LocalTensor<dataType> yOutLocal_;
621	    AscendC::LocalTensor<dataType> weightInLocal_;
622	    AscendC::LocalTensor<float> hsLocal_;
