638	public:
639	    __aicore__ inline void Init(
640	        GM_ADDR hs, GM_ADDR res, GM_ADDR weight, GM_ADDR y,
641	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
642	        int32_t tasksPerCore, float eps, float invN)
