675	    static constexpr uint32_t kTileFloatBytes = kBlockN * sizeof(float);
676	
677	    __aicore__ inline int32_t NumTiles() const
678	    {
679	        return (N + kBlockN - 1) / kBlockN;
680	    }
681	
682	    __aicore__ inline int32_t GetValidN(int32_t colBase) const
683	    {
