687	    __aicore__ inline void CopyInHs(int32_t rowIdx, int32_t colBase, int32_t validN)
688	    {
689	        hsInLocal_ = hsInQueue_.AllocTensor<dataType>();
690	        LoadGmToUb(hsInLocal_, hsGM_[static_cast<uint64_t>(rowIdx) * N + colBase], static_cast<uint32_t>(validN));
691	        hsInQueue_.EnQue(hsInLocal_);
692	    }
693	
694	    __aicore__ inline void CopyInRes(int32_t rowIdx, int32_t colBase, int32_t validN)
695	    {
696	        resInLocal_ = resInQueue_.AllocTensor<dataType>();
697	        LoadGmToUb(resInLocal_, resGM_[static_cast<uint64_t>(rowIdx) * N + colBase], static_cast<uint32_t>(validN));
698	        resInQueue_.EnQue(resInLocal_);
699	    }
700	
701	    __aicore__ inline void CopyInWeight(int32_t colBase, int32_t validN)
702	    {
703	        weightInLocal_ = weightInQueue_.AllocTensor<dataType>();
704	        LoadGmToUb(weightInLocal_, weightGM_[colBase], static_cast<uint32_t>(validN));
705	        weightInQueue_.EnQue(weightInLocal_);
