707	
708	    __aicore__ inline void CopyOutY(int32_t rowIdx, int32_t colBase, int32_t validN)
709	    {
710	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
711	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N + colBase], yOutLocal_, static_cast<uint32_t>(validN));
712	        yOutQueue_.FreeTensor(yOutLocal_);
713	    }
714	
715	    __aicore__ inline float ComputeInvRms(int32_t rowIdx)
716	    {
717	        reduceLocal_ = reduceBuf_.Get<float>();
718	        sumLocal_ = sumBuf_.Get<float>();
719	        tempLocal_ = tempBuf_.Get<float>();
720	        addLocal_ = addBuf_.Get<float>();
721	        float sumSq = 0.0f;
722	
723	        for (int by = 0; by < NumTiles(); ++by) {
724	            const int colBase = by * kBlockN;
725	            const int validN = GetValidN(colBase);
726	
727	            CopyInHs(rowIdx, colBase, validN);
728	            CopyInRes(rowIdx, colBase, validN);
729	
730	            hsInLocal_ = hsInQueue_.DeQue<dataType>();
731	            resInLocal_ = resInQueue_.DeQue<dataType>();
732	            PrepareInputTensorHelper<dataType>(hsLocal_, hsInLocal_, hsCastBuf_, validN);
733	            PrepareInputTensorHelper<dataType>(resLocal_, resInLocal_, resCastBuf_, validN);
734	
735	            // x = hidden_states + residual
736	            AscendC::Add(addLocal_, hsLocal_, resLocal_, validN);
737	            // x^2
738	            AscendC::Mul(tempLocal_, addLocal_, addLocal_, validN);
739	            AscendC::ReduceSum<float>(sumLocal_, tempLocal_, reduceLocal_, validN);
740	            sumSq += sumLocal_.GetValue(0);
741	
742	            hsInQueue_.FreeTensor(hsInLocal_);
743	            resInQueue_.FreeTensor(resInLocal_);
744	        }
745	
746	        AscendC::Duplicate(sumLocal_, sumSq * invN + eps, 1);
747	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, 1);
748	        AscendC::PipeBarrier<PIPE_ALL>();
749	        float invRms = invRmsLocal_.GetValue(0);
750	        AscendC::PipeBarrier<PIPE_ALL>();
751	        return invRms;
752	    }
753	
754	    __aicore__ inline void ComputeTile(float invRms, int32_t validN)
755	    {
756	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
757	        hsInLocal_ = hsInQueue_.DeQue<dataType>();
758	        resInLocal_ = resInQueue_.DeQue<dataType>();
759	        weightInLocal_ = weightInQueue_.DeQue<dataType>();
760	        PrepareInputTensorHelper<dataType>(hsLocal_, hsInLocal_, hsCastBuf_, validN);
761	        PrepareInputTensorHelper<dataType>(resLocal_, resInLocal_, resCastBuf_, validN);
762	        PrepareInputTensorHelper<dataType>(weightLocal_, weightInLocal_, weightCastBuf_, validN);
763	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
764	        addLocal_ = addBuf_.Get<float>();
765	
766	        // x = hidden_states + residual
767	        AscendC::Add(addLocal_, hsLocal_, resLocal_, validN);
768	        // x * rsqrt
769	        AscendC::Muls(yLocal_, addLocal_, invRms, validN);
770	        // * weight
771	        AscendC::Mul(yLocal_, yLocal_, weightLocal_, validN);
772	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, validN);
773	        hsInQueue_.FreeTensor(hsInLocal_);
774	        resInQueue_.FreeTensor(resInLocal_);
775	        weightInQueue_.FreeTensor(weightInLocal_);
776	        yOutQueue_.EnQue(yOutLocal_);
777	    }
778	
779	    __aicore__ inline void ProcessRow(int rowIdx)
780	    {
781	        float invRms = ComputeInvRms(rowIdx);
782	
783	        for (int by = 0; by < NumTiles(); ++by) {
784	            const int colBase = by * kBlockN;
785	            const int validN = GetValidN(colBase);
786	
787	            CopyInHs(rowIdx, colBase, validN);
788	            CopyInRes(rowIdx, colBase, validN);
789	            CopyInWeight(colBase, validN);
790	            ComputeTile(invRms, validN);
791	            CopyOutY(rowIdx, colBase, validN);
792	        }
793	    }
794	
795	private:
796	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> hsInQueue_;
797	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> resInQueue_;
798	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> weightInQueue_;
799	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
800	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
801	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
802	    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBuf_;
803	    AscendC::TBuf<AscendC::TPosition::VECCALC> invRmsBuf_;
804	    AscendC::TBuf<AscendC::TPosition::VECCALC> addBuf_;
805	    AscendC::TBuf<AscendC::TPosition::VECCALC> hsCastBuf_;
806	    AscendC::TBuf<AscendC::TPosition::VECCALC> resCastBuf_;
807	    AscendC::TBuf<AscendC::TPosition::VECCALC> weightCastBuf_;
808	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
809	
810	    AscendC::LocalTensor<dataType> hsInLocal_;
811	    AscendC::LocalTensor<dataType> resInLocal_;
812	    AscendC::LocalTensor<dataType> weightInLocal_;
813	    AscendC::LocalTensor<dataType> yOutLocal_;
814	    AscendC::LocalTensor<float> invRmsLocal_;
815	    AscendC::LocalTensor<float> hsLocal_;
816	    AscendC::LocalTensor<float> resLocal_;
817	    AscendC::LocalTensor<float> weightLocal_;
818	    AscendC::LocalTensor<float> yLocal_;
819	    AscendC::LocalTensor<float> addLocal_;
820	    AscendC::LocalTensor<float> reduceLocal_;
821	    AscendC::LocalTensor<float> sumLocal_;
822	    AscendC::LocalTensor<float> tempLocal_;
823	};
824	
825	// =========================================================================
826	// Shared dtype-dispatch helper — eliminates the duplicated if/else-if/else chains
827	// =========================================================================
828	
829	template <template <typename> class Kernel, typename... ExtraArgs>
830	__aicore__ inline void DispatchFusedAddRmsnorm(
831	    GM_ADDR hs, GM_ADDR res, GM_ADDR weight, GM_ADDR y,
832	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
833	    int32_t tasksPerCore, float eps, float invN,
834	    int64_t dtypeFlag, ExtraArgs... extraArgs)
835	{
836	    if (dtypeFlag == 0) {
837	        Kernel<float> kernel;
838	        kernel.Init(hs, res, weight, y, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
839	        kernel.Process();
840	    } else if (dtypeFlag == 1) {
841	        Kernel<half> kernel;
842	        kernel.Init(hs, res, weight, y, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
843	        kernel.Process();
844	    } else {
845	        Kernel<bfloat16_t> kernel;
846	        kernel.Init(hs, res, weight, y, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
847	        kernel.Process();
848	    }
849	}
850	
851	// =========================================================================
852	// Kernel entry points — Abs-style: single __global__ per strategy with dtype dispatch
853	// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
854	// =========================================================================
855	
856	extern "C" __global__ __aicore__ void fused_add_rmsnorm_merge_n(
857	    GM_ADDR hs, GM_ADDR res, GM_ADDR weight, GM_ADDR y,
858	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
859	    int32_t tasksPerCore, int32_t rowFactor, float eps, float invN,
860	    int64_t dtypeFlag)
861	{
862	    DispatchFusedAddRmsnorm<FusedAddRmsnormMergeNKernel>(
863	        hs, res, weight, y, M, N, blockM, usedCoreNum, tasksPerCore,
864	        eps, invN, dtypeFlag, rowFactor);
865	}
866	
867	extern "C" __global__ __aicore__ void fused_add_rmsnorm_single_row(
868	    GM_ADDR hs, GM_ADDR res, GM_ADDR weight, GM_ADDR y,
869	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
870	    int32_t tasksPerCore, float eps, float invN,
871	    int64_t dtypeFlag)
872	{
873	    DispatchFusedAddRmsnorm<FusedAddRmsnormSingleRowKernel>(
874	        hs, res, weight, y, M, N, blockM, usedCoreNum, tasksPerCore,
875	        eps, invN, dtypeFlag);
876	}
877	
878	extern "C" __global__ __aicore__ void fused_add_rmsnorm_splitd(
879	    GM_ADDR hs, GM_ADDR res, GM_ADDR weight, GM_ADDR y,
880	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
881	    int32_t tasksPerCore, float eps, float invN,
882	    int64_t dtypeFlag)
883	{
884	    DispatchFusedAddRmsnorm<FusedAddRmsnormSplitDKernel>(
885	        hs, res, weight, y, M, N, blockM, usedCoreNum, tasksPerCore,
886	        eps, invN, dtypeFlag);
887	}
