11	// FusedAddRmsnorm op_host — tiling calculation + strategy dispatch + EXEC_KERNEL_CMD launch
12	// Format: Abs-style with platform_ascendc and EXEC_KERNEL_CMD
13	
14	#include <algorithm>
15	#include <cstdint>
