26	
27	// ---------------------------------------------------------------------------
28	// Tiling constants
29	// ---------------------------------------------------------------------------
30	
31	constexpr int32_t DEFAULT_BLOCK_M = 64;
32	constexpr int32_t DEFAULT_ROW_FACTOR = 8;
33	constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
34	
35	// ---------------------------------------------------------------------------
36	// Host function
37	// ---------------------------------------------------------------------------
38	
39	namespace ascend_kernel {
40	
41	at::Tensor fused_add_rmsnorm(
42	    const at::Tensor &hidden_states,
43	    const at::Tensor &residual,
44	    const at::Tensor &weight,
45	    double eps)
46	{
47	    TORCH_CHECK(hidden_states.dim() == 2, "hidden_states must be [B, N]");
48	    TORCH_CHECK(residual.dim() == 2, "residual must be [B, N]");
49	    TORCH_CHECK(weight.dim() == 1, "weight must be [N]");
50	    TORCH_CHECK(
51	        hidden_states.scalar_type() == at::kFloat || hidden_states.scalar_type() == at::kHalf ||
52	            hidden_states.scalar_type() == at::kBFloat16,
53	        "hidden_states must be float32, float16, or bfloat16");
54	    TORCH_CHECK(hidden_states.scalar_type() == residual.scalar_type(),
55	        "residual must have the same dtype as hidden_states");
56	    TORCH_CHECK(hidden_states.scalar_type() == weight.scalar_type(),
57	        "weight must have the same dtype as hidden_states");
58	    TORCH_CHECK(hidden_states.is_contiguous(), "hidden_states must be contiguous");
59	    TORCH_CHECK(residual.is_contiguous(), "residual must be contiguous");
60	    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
61	    TORCH_CHECK(static_cast<int32_t>(hidden_states.sizes()[1]) == static_cast<int32_t>(weight.sizes()[0]),
62	        "weight shape mismatch");
63	
64	    int32_t M = static_cast<int32_t>(hidden_states.sizes()[0]);
65	    int32_t N = static_cast<int32_t>(hidden_states.sizes()[1]);
66	
67	    int32_t mNum = (M + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
68	    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, mNum));
69	    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;
70	
71	    at::Tensor y = at::empty_like(hidden_states);
72	
73	    // dtype flag: 0=fp32, 1=fp16, 2=bf16
74	    int64_t dtypeFlag = 0;
75	    if (hidden_states.scalar_type() == at::kHalf) {
76	        dtypeFlag = 1;
77	    } else if (hidden_states.scalar_type() == at::kBFloat16) {
78	        dtypeFlag = 2;
79	    }
80	
81	    // All tiling params as left values (required by EXEC_KERNEL_CMD)
82	    int32_t blockM = DEFAULT_BLOCK_M;
83	    int32_t rowFactor = DEFAULT_ROW_FACTOR;
84	    float epsVal = static_cast<float>(eps);
85	    float invN = 1.0f / static_cast<float>(N);
86	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
87	
88	    // Strategy dispatch: select kernel name and params
89	    if (N <= 1024) {
90	        EXEC_KERNEL_CMD(fused_add_rmsnorm_merge_n, blockDim,
91	                        hidden_states, residual, weight, y,
92	                        M, N, blockM, usedCoreNum, tasksPerCore, rowFactor, epsVal, invN,
93	                        dtypeFlag);
94	    } else if (N > 8192) {
95	        EXEC_KERNEL_CMD(fused_add_rmsnorm_splitd, blockDim,
96	                        hidden_states, residual, weight, y,
97	                        M, N, blockM, usedCoreNum, tasksPerCore, epsVal, invN,
98	                        dtypeFlag);
99	    } else {
100	        EXEC_KERNEL_CMD(fused_add_rmsnorm_single_row, blockDim,
101	                        hidden_states, residual, weight, y,
102	                        M, N, blockM, usedCoreNum, tasksPerCore, epsVal, invN,
103	                        dtypeFlag);
104	    }
105	
106	    return y;
107	}
