// AscendC GaussianTopkSparseActivation kernel
// Computes per-row: mean/std along D → threshold = mean + std * ndtri_val → relu(x - threshold)
// Input/output: bf16; internal compute: fp32

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t TILE_D = 256;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

template <typename T>
__aicore__ inline void PrepareInputTensorHelper(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline void FinalizeOutputTensorHelper(
    AscendC::LocalTensor<T> &out,
    AscendC::LocalTensor<float> &src,
    int32_t count)
{
    if constexpr (!std::is_same_v<T, float>) {
        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// =========================================================================
// GaussianTopkSparseActivation kernel — single-row, tiled-D strategy
// =========================================================================

template <typename dataType>
class GaussianTopkSparseActivationKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t N, int32_t D, int32_t nBlocks, int32_t blockN,
        int32_t tasksPerCore, float ndtriVal, float invD)
    {
        this->N = N;
        this->D = D;
        this->nBlocks = nBlocks;
        this->blockN = blockN;
        this->tasksPerCore = tasksPerCore;
        this->ndtriVal = ndtriVal;
        this->invD = invD;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(N) * D);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(N) * D);

        if ASCEND_IS_AIV {
            // TQue for GM↔UB double buffering
            pipe.InitBuffer(inQueue_, BUFFER_NUM, TILE_D * sizeof(dataType));
            pipe.InitBuffer(outQueue_, BUFFER_NUM, TILE_D * sizeof(dataType));
            // TBuf for fp32 compute
            pipe.InitBuffer(fp32Buf_, TILE_D * sizeof(float));
            pipe.InitBuffer(sqBuf_, TILE_D * sizeof(float));
            pipe.InitBuffer(reduceBuf_, TILE_D * sizeof(float));
            pipe.InitBuffer(sumBuf_, sizeof(float));
            pipe.InitBuffer(tileSumBuf_, sizeof(float));
            if constexpr (!std::is_same_v<dataType, float>) {
                pipe.InitBuffer(castBuf_, TILE_D * sizeof(float));
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= nBlocks) {
                    continue;
                }

                const int rowStart = bx * blockN;
                const int curRows = (rowStart + blockN <= N) ? blockN : (N - rowStart);

                for (int r = 0; r < curRows; ++r) {
                    ProcessRow(rowStart + r);
                }
            }
        }
    }

private:
    __aicore__ inline int32_t NumTiles() const
    {
        return (D + TILE_D - 1) / TILE_D;
    }

    __aicore__ inline int32_t GetCurLen(int32_t colBase) const
    {
        return (colBase + TILE_D <= D) ? TILE_D : (D - colBase);
    }

    // ================================================================
    // Phase 1: Reduction — accumulate sum and sum_sq across tiles
    // ================================================================

    __aicore__ inline void CopyInX(int32_t rowIdx, int32_t colBase, int32_t curLen)
    {
        inLocal_ = inQueue_.AllocTensor<dataType>();
        LoadGmToUb(inLocal_, xGM_[static_cast<uint64_t>(rowIdx) * D + colBase],
                   static_cast<uint32_t>(curLen));
        inQueue_.EnQue(inLocal_);
    }

    __aicore__ inline void ComputeReduction(int32_t curLen, float &tileSum, float &tileSumSq)
    {
        inLocal_ = inQueue_.DeQue<dataType>();
        PrepareInputTensorHelper<dataType>(fpLocal_, inLocal_, castBuf_, curLen);

        sqLocal_ = sqBuf_.Get<float>();
        reduceLocal_ = reduceBuf_.Get<float>();
        tileSumLocal_ = tileSumBuf_.Get<float>();
        sumLocal_ = sumBuf_.Get<float>();

        // ReduceSum for sum
        AscendC::ReduceSum<float>(tileSumLocal_, fpLocal_, reduceLocal_, curLen);
        AscendC::PipeBarrier<PIPE_ALL>();
        tileSum = tileSumLocal_.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();

        // x^2 + ReduceSum for sum of squares
        AscendC::Mul(sqLocal_, fpLocal_, fpLocal_, curLen);
        AscendC::ReduceSum<float>(sumLocal_, sqLocal_, reduceLocal_, curLen);
        AscendC::PipeBarrier<PIPE_ALL>();
        tileSumSq = sumLocal_.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();

        inQueue_.FreeTensor(inLocal_);
    }

    // ================================================================
    // Phase 2: Activation — sub threshold, relu, cast, write
    // ================================================================

    __aicore__ inline void ComputeActivation(int32_t curLen, float threshold)
    {
        inLocal_ = inQueue_.DeQue<dataType>();
        outLocal_ = outQueue_.AllocTensor<dataType>();
        PrepareInputTensorHelper<dataType>(fpLocal_, inLocal_, castBuf_, curLen);

        // x - threshold = x + (-threshold)
        float negThreshold = -threshold;
        AscendC::Adds(fpLocal_, fpLocal_, negThreshold, curLen);
        // relu
        AscendC::Relu(fpLocal_, fpLocal_, curLen);

        // Cast fp32 → output dtype and write to outQueue
        FinalizeOutputTensorHelper<dataType>(outLocal_, fpLocal_, curLen);

        inQueue_.FreeTensor(inLocal_);
        outQueue_.EnQue(outLocal_);
    }

    __aicore__ inline void CopyOutY(int32_t rowIdx, int32_t colBase, int32_t curLen)
    {
        outLocal_ = outQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * D + colBase],
                    outLocal_, static_cast<uint32_t>(curLen));
        outQueue_.FreeTensor(outLocal_);
    }

    // ================================================================
    // Per-row processing
    // ================================================================

    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        const int numTiles = NumTiles();

        // ---- Phase 1: Reduction ----
        float sumVal = 0.0f;
        float sumSqVal = 0.0f;

        for (int t = 0; t < numTiles; ++t) {
            int32_t colBase = t * TILE_D;
            int32_t curLen = GetCurLen(colBase);
            CopyInX(rowIdx, colBase, curLen);
            float tileSum;
            float tileSumSq;
            ComputeReduction(curLen, tileSum, tileSumSq);
            sumVal += tileSum;
            sumSqVal += tileSumSq;
        }

        // Compute stats: mean, var, std, threshold
        float meanVal = sumVal * invD;
        float varVal = sumSqVal * invD - meanVal * meanVal;
        if (varVal < 0.0f) { varVal = 0.0f; }
        float stdVal = sqrtf(varVal);
        float threshold = meanVal + stdVal * ndtriVal;

        // ---- Phase 2: Activation ----
        for (int t = 0; t < numTiles; ++t) {
            int32_t colBase = t * TILE_D;
            int32_t curLen = GetCurLen(colBase);
