// GaussianTopkSparseActivation op_host — tiling calculation + EXEC_KERNEL_CMD launch
// ndtri(target_sparsity) is pre-computed on host

#include <algorithm>
#include <cmath>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_gaussian_topk_sparse_activation.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------

constexpr int32_t DEFAULT_BLOCK_N = 64;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

// ---------------------------------------------------------------------------
// ndtri Abramowitz & Stegun approximation (host-side)
// ---------------------------------------------------------------------------

namespace {

constexpr float NDTRI_A[] = {
    -3.969683028665376e+01f, 2.209460984245205e+02f, -2.759285104469687e+02f,
    1.383577518672690e+02f, -3.066479806614716e+01f, 2.506628277459239e+00f};
constexpr float NDTRI_B[] = {
    -5.447609879822406e+01f, 1.615858368580409e+02f, -1.556989798598866e+02f,
    6.680131188771972e+01f, -1.328068155288572e+01f};
constexpr float NDTRI_C[] = {
    -7.784894002430293e-03f, -3.223964580411365e-01f, -2.400758277161838e+00f,
    -2.549732539343734e+00f, 4.374664141464968e+00f, 2.938163982698783e+00f};
constexpr float NDTRI_D[] = {
    7.784695709041462e-03f, 3.224671290700398e-01f, 2.445134137142996e+00f,
    3.754408661907416e+00f};
constexpr float NDTRI_P_LOW = 0.02425f;
constexpr float NDTRI_P_HIGH = 0.97575f;  // 1.0 - 0.02425

float ComputeNdTri(float p)
{
    if (p < NDTRI_P_LOW) {
        float q = std::sqrt(-2.0f * std::log(p));
        float num = (((((NDTRI_C[0] * q + NDTRI_C[1]) * q + NDTRI_C[2]) * q +
                        NDTRI_C[3]) * q + NDTRI_C[4]) * q + NDTRI_C[5]);
        float den = ((((NDTRI_D[0] * q + NDTRI_D[1]) * q + NDTRI_D[2]) * q +
                       NDTRI_D[3]) * q + 1.0f);
        return num / den;
    } else if (p > NDTRI_P_HIGH) {
        float q = std::sqrt(-2.0f * std::log(1.0f - p));
        float num = (((((NDTRI_C[0] * q + NDTRI_C[1]) * q + NDTRI_C[2]) * q +
                        NDTRI_C[3]) * q + NDTRI_C[4]) * q + NDTRI_C[5]);
        float den = ((((NDTRI_D[0] * q + NDTRI_D[1]) * q + NDTRI_D[2]) * q +
                       NDTRI_D[3]) * q + 1.0f);
        return -(num / den);
    } else {
        float q = p - 0.5f;
        float r = q * q;
        float num = (((((NDTRI_A[0] * r + NDTRI_A[1]) * r + NDTRI_A[2]) * r +
                        NDTRI_A[3]) * r + NDTRI_A[4]) * r + NDTRI_A[5]) * q;
        float den = (((((NDTRI_B[0] * r + NDTRI_B[1]) * r + NDTRI_B[2]) * r +
                        NDTRI_B[3]) * r + NDTRI_B[4]) * r + 1.0f);
        return num / den;
    }
}

}  // anonymous namespace

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------

namespace ascend_kernel {

at::Tensor gaussian_topk_sparse_activation(
    const at::Tensor &inputs,
    double target_sparsity)
{
    TORCH_CHECK(inputs.dim() == 3, "inputs must be [B, S, D]");
    TORCH_CHECK(
        inputs.scalar_type() == at::kFloat || inputs.scalar_type() == at::kHalf ||
            inputs.scalar_type() == at::kBFloat16,
        "inputs must be float32, float16, or bfloat16");
    TORCH_CHECK(inputs.is_contiguous(), "inputs must be contiguous");

    // Handle pass-through for zero sparsity
    if (target_sparsity <= 0.0) {
        return inputs;
    }

    int32_t B = static_cast<int32_t>(inputs.sizes()[0]);
    int32_t S = static_cast<int32_t>(inputs.sizes()[1]);
    int32_t Dim = static_cast<int32_t>(inputs.sizes()[2]);
    int32_t N = B * S;
    int32_t D = Dim;

    // Tiling: row-based block partitioning
    int32_t nBlocks = (N + DEFAULT_BLOCK_N - 1) / DEFAULT_BLOCK_N;
    int32_t usedCores = std::min<int32_t>(
        DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, nBlocks));
    int32_t tasksPerCore = (nBlocks + usedCores - 1) / usedCores;

    // Compute ndtri on host
    float ndtriVal = ComputeNdTri(static_cast<float>(target_sparsity));

    // Output: same shape as input, bf16
    at::Tensor y = at::empty_like(inputs);

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (inputs.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (inputs.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    int32_t nBlocksLeft = nBlocks;
    int32_t blockNLeft = DEFAULT_BLOCK_N;
    int32_t tasksPerCoreLeft = tasksPerCore;
    float invD = 1.0f / static_cast<float>(D);
    uint32_t blockDim = static_cast<uint32_t>(usedCores);

    EXEC_KERNEL_CMD(gaussian_topk_sparse_activation, blockDim,
                    inputs, y,
                    N, D, nBlocksLeft, blockNLeft, tasksPerCoreLeft,
                    ndtriVal, invD, dtypeFlag);

    return y;
}

}  // namespace ascend_kernel
